  "python": {
    "ce": "# Relation styles — exported by Manim Formula Editor for ManimCE 0.22.\n# Render at 1920×1080, 60 fps:\n#     manim -r 1920,1080 --fps 60 RelationStyles.py RelationStyles\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 312 frames, like the editor's video export.\nfrom manim import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass RelationStyles(Scene):\n    def construct(self):\n        self.camera.background_color = \"#000000\"\n\n        # xy: x+y\n        xy = MathTex(r\"x+y\", font_size=96)\n        xy_g = _glyphs(xy, [\n            (-1.1225, 0.0336, 0.618, 0.5749), (0.0256, 0.078, 0.8452, 0.8439), (1.1297, -0.089, 0.6036, 0.8219),\n        ])\n        xy.move_to([0, 1.1, 0])\n        xy.set_z_index(1)\n\n        # yx: y+x\n        yx = MathTex(r\"y+x\", font_size=96)\n        yx_g = _glyphs(yx, [\n            (-1.1026, -0.089, 0.6036, 0.8219), (-0.0336, 0.078, 0.8452, 0.8439), (1.0954, 0.0336, 0.618, 0.5749),\n        ])\n        yx.move_to([0, -1.1, 0])\n\n        # 0 s – 1 s: xy write\n        self.play(Write(VGroup(*xy_g[:])), run_time=1)\n        # 1 s – 2.2 s\n        self.wait(1.2)\n        # 2.2 s – 3.4 s: xy → yx\n        self.play(\n            ReplacementTransform(xy_g[0], yx_g[2]),\n            ReplacementTransform(xy_g[1], yx_g[1]),\n            ReplacementTransform(xy_g[2], yx_g[0]),\n            run_time=1.2,\n        )\n        # 3.4 s – 5.2 s\n        self.wait(1.8)\n",
    "gl": "# Relation styles — exported by Manim Formula Editor for ManimGL 1.7.\n# Render at 1920×1080, 60 fps:\n#     manimgl RelationStyles.py RelationStyles -w -r 1920x1080 --fps 60\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 312 frames, like the editor's video export.\nfrom manimlib import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass RelationStyles(Scene):\n    default_camera_config = dict(background_color=\"#000000\")\n\n    def construct(self):\n\n        # xy: x+y\n        xy = Tex(r\"x+y\", font_size=98.9888)\n        xy_g = _glyphs(xy, [\n            (-1.1225, 0.0336, 0.618, 0.5749), (0.0256, 0.078, 0.8452, 0.8439), (1.1297, -0.089, 0.6036, 0.8219),\n        ])\n        xy.move_to([0, 1.1, 0])\n        xy.set_z_index(1)\n\n        # yx: y+x\n        yx = Tex(r\"y+x\", font_size=98.9888)\n        yx_g = _glyphs(yx, [\n            (-1.1026, -0.089, 0.6036, 0.8219), (-0.0336, 0.078, 0.8452, 0.8439), (1.0954, 0.0336, 0.618, 0.5749),\n        ])\n        yx.move_to([0, -1.1, 0])\n\n        # 0 s – 1 s: xy write\n        self.play(Write(VGroup(*xy_g[:]), stroke_color=\"#FFFFFF\"), run_time=1)\n        # 1 s – 2.2 s\n        self.wait(1.2)\n        # 2.2 s – 3.4 s: xy → yx\n        self.play(\n            ReplacementTransform(xy_g[0], yx_g[2]),\n            ReplacementTransform(xy_g[1], yx_g[1]),\n            ReplacementTransform(xy_g[2], yx_g[0]),\n            run_time=1.2,\n        )\n        # 3.4 s – 5.2 s\n        self.wait(1.8)\n"
  },
